using System;using System.Linq;using System.IO;using System.Collections.Generic;using System.Reflection;
using UnityEngine;using UnityEngine.UI;using UnityEditor;using TMPro;using CatGunner.Recovery;
public static class AuditPenguinRemaining
{
 static string Dir=>Path.GetFullPath(Application.dataPath+"/../../../art/reskin/penguin-expedition/theme-audit");
 static string P(Transform t){string p=t.name;while(t.parent!=null){t=t.parent;p=t.name+"/"+p;}return p;}
 static object S(Sprite s)=>s==null?null:new{s.name,asset=AssetDatabase.GetAssetPath(s),width=s.rect.width,height=s.rect.height,border=s.border.ToString()};
 static bool Original(UnityEngine.Object asset){var path=AssetDatabase.GetAssetPath(asset);return !string.IsNullOrEmpty(path)&&!path.StartsWith("Assets/Recovery/")&&!path.StartsWith("Resources/unity_builtin")&&!path.StartsWith("Library/")&&!(asset is Sprite s&&PenguinFullReskin.IsOriginalGlow(s));}
 public static string Run()
 {
  if(Application.dataPath!="/Volumes/ZHITAI_1T/IdleCatGunner/reconstruction/CatGunnerUnityClient/Assets")throw new Exception("Wrong project");
  var c=UnityEngine.Object.FindAnyObjectByType<RecoveryForestClient>(FindObjectsInactive.Include);var roots=c.gameObject.scene.GetRootGameObjects();Directory.CreateDirectory(Dir);
  var images=roots.SelectMany(g=>g.GetComponentsInChildren<Image>(true)).Where(i=>Original(i.sprite)&&i.enabled).GroupBy(i=>i.sprite).Select(g=>new{sprite=S(g.Key),count=g.Count(),paths=g.Select(i=>new{path=P(i.transform),active=i.gameObject.activeInHierarchy,color=i.color.ToString(),material=i.material.name,type=i.type.ToString()}).ToArray()}).ToArray();
  var sprites=roots.SelectMany(g=>g.GetComponentsInChildren<SpriteRenderer>(true)).Where(r=>Original(r.sprite)&&r.enabled).GroupBy(r=>r.sprite).Select(g=>new{sprite=S(g.Key),count=g.Count(),paths=g.Select(r=>new{path=P(r.transform),active=r.gameObject.activeInHierarchy,color=r.color.ToString()}).ToArray()}).ToArray();
  var raw=roots.SelectMany(g=>g.GetComponentsInChildren<RawImage>(true)).Where(r=>r.enabled&&r.texture!=null&&!(r.texture is RenderTexture)&&Original(r.texture)).Select(r=>new{path=P(r.transform),r.texture.name,asset=AssetDatabase.GetAssetPath(r.texture),active=r.gameObject.activeInHierarchy}).ToArray();
  var states=roots.SelectMany(g=>g.GetComponentsInChildren<Selectable>(true)).Select(b=>new{path=P(b.transform),states=new[]{b.spriteState.highlightedSprite,b.spriteState.pressedSprite,b.spriteState.selectedSprite,b.spriteState.disabledSprite}.Where(s=>s!=null&&Original(s)).Select(S).ToArray()}).Where(b=>b.states.Length>0).ToArray();
  var fields=roots.SelectMany(g=>g.GetComponentsInChildren<MonoBehaviour>(true)).Where(b=>b!=null&&!(b is Graphic)&&!(b is PenguinFullReskin)&&!(b is PenguinExpeditionTheme)&&!(b is PenguinUiTheme)).SelectMany(b=>b.GetType().GetFields(BindingFlags.Public|BindingFlags.Instance).Where(f=>f.FieldType==typeof(Sprite)||f.FieldType==typeof(Sprite[])).Select(f=>new{type=b.GetType().Name,path=P(b.transform),f.Name,sprites=(f.FieldType==typeof(Sprite)?new[]{(Sprite)f.GetValue(b)}:(Sprite[])f.GetValue(b)??Array.Empty<Sprite>()).Where(s=>s!=null&&Original(s)).Select(S).ToArray()})).Where(f=>f.sprites.Length>0).ToArray();
  var mesh=roots.SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r.enabled&&!(r is SpriteRenderer)&&!(r is ParticleSystemRenderer)).Select(r=>new{path=P(r.transform),type=r.GetType().Name,active=r.gameObject.activeInHierarchy,materials=r.sharedMaterials.Where(m=>m!=null&&Original(m.mainTexture)).Select(m=>new{m.name,texture=m.mainTexture.name,asset=AssetDatabase.GetAssetPath(m.mainTexture),shader=m.shader.name}).ToArray()}).Where(r=>r.materials.Length>0).ToArray();
  var text=roots.SelectMany(g=>g.GetComponentsInChildren<TMP_Text>(true)).Where(t=>t.enabled&&(t.text.Contains("猫")||t.text.Contains("树")||t.text.Contains("小猪")||t.text.Contains("森林")||t.text.ToLowerInvariant().Contains("meow")||t.text.ToLowerInvariant().Contains("cat"))).Select(t=>new{path=P(t.transform),t.text,active=t.gameObject.activeInHierarchy}).ToArray();
  var preservedGlows=roots.SelectMany(g=>g.GetComponentsInChildren<Image>(true)).Where(i=>i.sprite!=null&&PenguinFullReskin.IsOriginalGlow(i.sprite)).Select(i=>new{path=P(i.transform),sprite=S(i.sprite),reason="User requested original glow style"}).ToArray();
  var nativeRings=roots.SelectMany(g=>g.GetComponentsInChildren<ParticleSystem>(true)).Where(p=>p.GetComponent<ParticleSystemRenderer>()?.sharedMaterial!=null&&PenguinPolarRing.IsRing(p,p.GetComponent<ParticleSystemRenderer>())).Select(p=>new{path=P(p.transform),texture=p.GetComponent<ParticleSystemRenderer>().sharedMaterial.mainTexture?.name,atlas=p.textureSheetAnimation.enabled,reason="User requested native ring atlas, rotation, mesh and timing"}).ToArray();
  var nativeAttacks=roots.SelectMany(g=>g.GetComponentsInChildren<ParticleSystem>(true)).Where(p=>p.GetComponentInParent<Bullet>(true)!=null||p.GetComponentInParent<Bullet_FX>(true)!=null||p.GetComponentInParent<Gun>(true)!=null).Select(p=>new{path=P(p.transform),texture=p.GetComponent<ParticleSystemRenderer>()?.sharedMaterial?.mainTexture?.name,reason="User requested original animated attack atlas; static effects-00 and effects-02 rejected"}).ToArray();
  var result=new{nativeAttacks,play=Application.isPlaying,images,sprites,raw,states,fields,mesh,text,preservedGlows,nativeRings};
  File.WriteAllText(Path.Combine(Dir,Application.isPlaying?"remaining-runtime.json":"remaining-editor.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));
  return "Original asset groups: images="+images.Length+", sprites="+sprites.Length+", raw="+raw.Length+", buttonStates="+states.Length+", fields="+fields.Length+", meshes="+mesh.Length+", wording="+text.Length;
 }
}
